<?php get_header(); $posts=get_posts(['post_type'=>'post','numberposts'=>-1,'post_status'=>'publish']); ?><main class="cm-content-wrap"><div class="section-kicker">CARTMAKERS INSIGHTS</div><h1>أفكار تساعدك تبيع أوضح</h1><p class="cm-copy">ملاحظات عملية عن المتاجر والمواقع والـCheckout والتتبع والنمو.</p><div class="cm-post-grid"><?php foreach($posts as $post): ?><article class="cm-card"><a href="<?php echo esc_url(get_permalink($post)); ?>"><?php if(has_post_thumbnail($post))echo get_the_post_thumbnail($post,'large',['loading'=>'lazy']); ?><div class="cm-meta">INSIGHT</div><h2><?php echo esc_html(get_the_title($post)); ?></h2><p><?php echo esc_html(cm_excerpt_text($post)); ?></p></a></article><?php endforeach; ?></div></main><?php get_footer(); ?>
